import Foundation

public struct Choice: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let text: String
}
public struct MatchingPair: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let left: String
    public let right: String
}
public struct Question: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let prompt: String
    public let kind: String
    public let options: [Choice]
    public let answer: String
    public let words: [Choice]
    public let answerWords: [String]
    public let pairs: [MatchingPair]
    public let explanation: String
    enum CodingKeys: String, CodingKey {
        case id, prompt, kind, options, answer, words, pairs, explanation
        case answerWords = "answer_words"
    }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        prompt = try c.decode(String.self, forKey: .prompt)
        kind = try c.decodeIfPresent(String.self, forKey: .kind) ?? "choice"
        options = try c.decodeIfPresent([Choice].self, forKey: .options) ?? []
        answer = try c.decodeIfPresent(String.self, forKey: .answer) ?? ""
        words = try c.decodeIfPresent([Choice].self, forKey: .words) ?? []
        answerWords = try c.decodeIfPresent([String].self, forKey: .answerWords) ?? []
        pairs = try c.decodeIfPresent([MatchingPair].self, forKey: .pairs) ?? []
        explanation = try c.decode(String.self, forKey: .explanation)
    }
    var valid: Bool {
        switch kind {
        case "choice": return !options.isEmpty && Set(options.map(\.id)).count == options.count && options.contains { $0.id == answer }
        case "word_tiles": return !answerWords.isEmpty && Set(words.map(\.id)).count == words.count && Set(answerWords).count == answerWords.count && answerWords.allSatisfy { id in words.contains { $0.id == id } }
        case "matching": return !pairs.isEmpty && Set(pairs.map(\.id)).count == pairs.count
        default: return false
        }
    }
    public var correction: String {
        switch kind {
        case "word_tiles": return answerWords.compactMap { id in words.first { $0.id == id }?.text }.joined(separator: " ")
        case "matching": return pairs.map { $0.left + " — " + $0.right }.joined(separator: ", ")
        default: return options.first { $0.id == answer }?.text ?? ""
        }
    }
}
public struct CourseLesson: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let questions: [Question]
}
public struct Course: Codable, Equatable, Sendable, Identifiable {
    public let id: String
    public let title: String
    public let lessons: [CourseLesson]
    public var questions: [Question] { lessons[0].questions }
    enum CodingKeys: String, CodingKey { case id, title, lessons, questions }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        title = try c.decode(String.self, forKey: .title)
        if let definitions = try c.decodeIfPresent([CourseLesson].self, forKey: .lessons) { lessons = definitions }
        else { lessons = [CourseLesson(id: id, title: title, questions: try c.decode([Question].self, forKey: .questions))] }
    }
    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id); try c.encode(title, forKey: .title); try c.encode(lessons, forKey: .lessons)
    }
    public static func readFixture(_ url: URL) throws -> Course {
        struct DataSection: Decodable { let candidate_course: Course }
        struct Fixture: Decodable { let data: DataSection }
        let course = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url)).data.candidate_course
        guard !course.lessons.isEmpty, Set(course.lessons.map(\.id)).count == course.lessons.count,
              course.lessons.allSatisfy({ !$0.questions.isEmpty && Set($0.questions.map(\.id)).count == $0.questions.count && $0.questions.allSatisfy(\.valid) }) else { throw CocoaError(.fileReadCorruptFile) }
        return course
    }
}

public struct Lesson: Equatable, Sendable {
    public let course: Course
    public let lessonIndex: Int
    public private(set) var position = 0
    public private(set) var selected: String?
    public private(set) var selectedWords: [String] = []
    public private(set) var matchedPairs: Set<String> = []
    public private(set) var leftPair: String?
    public private(set) var rightPair: String?
    public private(set) var feedback: Bool?
    public private(set) var hearts = 5
    public private(set) var review = [Int]()
    public private(set) var reviewing = false
    public private(set) var complete = false
    public var definition: CourseLesson { course.lessons[lessonIndex] }
    public var question: Question { definition.questions[position] }
    public var canSubmit: Bool {
        guard feedback == nil, !complete else { return false }
        return question.kind == "choice" ? selected != nil : question.kind == "word_tiles" && !selectedWords.isEmpty
    }
    public init(course: Course, lessonIndex: Int = 0) {
        precondition(course.lessons.indices.contains(lessonIndex))
        self.course = course; self.lessonIndex = lessonIndex
    }
    public mutating func choose(_ id: String) {
        guard feedback == nil, !complete, question.kind == "choice", question.options.contains(where: { $0.id == id }) else { return }
        selected = id
    }
    public mutating func addWord(_ id: String) {
        guard feedback == nil, !complete, question.kind == "word_tiles", !selectedWords.contains(id), question.words.contains(where: { $0.id == id }) else { return }
        selectedWords.append(id)
    }
    public mutating func removeWord(_ id: String) {
        guard feedback == nil, !complete, question.kind == "word_tiles" else { return }
        selectedWords.removeAll { $0 == id }
    }
    public mutating func selectPair(_ id: String, left: Bool) {
        guard feedback == nil, !complete, question.kind == "matching", !matchedPairs.contains(id), question.pairs.contains(where: { $0.id == id }) else { return }
        if left { leftPair = id } else { rightPair = id }
        if let first = leftPair, let second = rightPair {
            if first == second { matchedPairs.insert(first) }
            leftPair = nil; rightPair = nil
            if matchedPairs.count == question.pairs.count { feedback = true }
        }
    }
    public mutating func submit() {
        guard canSubmit else { return }
        let correct = question.kind == "word_tiles" ? selectedWords == question.answerWords : selected == question.answer
        feedback = correct
        if !correct {
            hearts = max(0, hearts - 1)
            if !review.contains(position) { review.append(position) }
        }
    }
    private mutating func clearAnswer() {
        selected = nil; selectedWords = []; matchedPairs = []; leftPair = nil; rightPair = nil; feedback = nil
    }
    public mutating func advance() {
        guard feedback != nil, !complete else { return }
        if reviewing {
            if feedback == true { review.removeAll { $0 == position } }
        } else if position + 1 < definition.questions.count {
            position += 1; clearAnswer(); return
        } else { reviewing = true }
        if let next = review.first { position = next }
        else { complete = true }
        clearAnswer()
    }
}

public struct LearningProgress: Codable, Equatable, Sendable {
    public var completedCourses: Set<String> = []
    public var completedLessons: [String: Set<String>] = [:]
    public init() {}
    enum CodingKeys: String, CodingKey { case completedCourses, completedLessons }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        completedCourses = try c.decode(Set<String>.self, forKey: .completedCourses)
        completedLessons = try c.decodeIfPresent([String: Set<String>].self, forKey: .completedLessons) ?? [:]
    }
    public func count(in course: Course) -> Int {
        if completedCourses.contains(course.id) { return course.lessons.count }
        return course.lessons.prefix { completedLessons[course.id, default: []].contains($0.id) }.count
    }
    public mutating func finish(_ lesson: Lesson) {
        guard lesson.complete else { return }
        completedLessons[lesson.course.id, default: []].insert(lesson.definition.id)
        if count(in: lesson.course) == lesson.course.lessons.count { completedCourses.insert(lesson.course.id) }
    }
}
public struct ProgressStore: Sendable {
    public let url: URL
    public init(url: URL) { self.url = url }
    public func load() throws -> LearningProgress {
        guard FileManager.default.fileExists(atPath: url.path) else { return LearningProgress() }
        return try JSONDecoder().decode(LearningProgress.self, from: Data(contentsOf: url))
    }
    public func save(_ progress: LearningProgress) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try JSONEncoder().encode(progress).write(to: url, options: .atomic)
    }
}

